def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            if len(cells) >= 6:
                rs = [p[0] for p in cells]; cs = [p[1] for p in cells]
                comps.append((min(rs), max(rs), min(cs), max(cs), set(cells)))
    return comps


def transform(grid):
    """Return an 8-mark mask of the differences between translated motifs."""
    comps = _components(grid)
    best = None
    for i, a in enumerate(comps):
