            dr, dc = br0-ar0, bc0-ac0
            # Compare the shared area of the two components' bounding boxes,
            # aligning their top-left corners. The smaller motif may be clipped.
            r0, r1 = max(ar0, br0-dr), min(ar1, br1-dr)
            c0, c1 = max(ac0, bc0-dc), min(ac1, bc1-dc)
            if r0 > r1 or c0 > c1:
