            for r in range(r0, r1+1):
                for c in range(c0, c1+1):
                    va = grid[r][c]
                    vb = grid[r+dr][c+dc]
                    total += 1
                    if va and va == vb:
                        agree += 1
                    if va != vb:
                        diffs.append((r, c))
            # A translated duplicate has many same-color cells in common.
            # Favor agreement, then the number of matching colored cells.
            key = (agree, -len(diffs), total)
            if diffs and (best is None or key > best[0]):
